-- =====================================================================
--  Gravitas · Contatos com Prefeituras — Alegrete (MySQL)
--  51 registros. Rode DEPOIS de 01-schema.sql, no banco do site.
--
--  Pode ser rodado de novo sem duplicar: o ON DUPLICATE KEY UPDATE
--  atualiza o cadastro e NAO toca em status, responsavel, notas,
--  interacoes nem agendas -- o trabalho da equipe fica preservado.
--
--  Veio pronto em MySQL, do pacote entregue. A unica adaptacao foi o
--  nome das tabelas: aqui elas tem o prefixo contatos_, como o resto
--  do banco do site.
-- =====================================================================

-- Seed MySQL: Alegrete (51 registros).
-- Rode no phpMyAdmin (aba SQL) DEPOIS de schema.sql. Pode rodar de novo sem duplicar:
-- atualiza os dados cadastrais e preserva status, responsável, notas, histórico e agendas.
SET NAMES utf8mb4;
START TRANSACTION;
ON DUPLICATE KEY UPDATE nome = VALUES(nome), uf = VALUES(uf), populacao = VALUES(populacao), prefeito = VALUES(prefeito), vice = VALUES(vice), presidente_camara = VALUES(presidente_camara), cadeiras_camara = VALUES(cadeiras_camara), ordem = VALUES(ordem), resumo = VALUES(resumo);
ON DUPLICATE KEY UPDATE cidade_id = VALUES(cidade_id), grupo = VALUES(grupo), orgao = VALUES(orgao), cargo = VALUES(cargo), nome = VALUES(nome), partido = VALUES(partido), telefone = VALUES(telefone), whatsapp = VALUES(whatsapp), email = VALUES(email), endereco = VALUES(endereco), rede_social = VALUES(rede_social), obs_fonte = VALUES(obs_fonte), foto = VALUES(foto), ordem = VALUES(ordem), prioritario = VALUES(prioritario), vinculado_a = VALUES(vinculado_a);
COMMIT;
